'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { formatCurrency } from '@/lib/utils'
import { createOrder, addMilestone } from '@/lib/actions/sale'

type Line = { id: string; description: string; qty: number; unitPrice: number }
type Milestone = { id: string; name: string; percent: number; dueDate: string }

export default function NewSalePage() {
    const router = useRouter()
    const [partnerName, setPartnerName] = useState('')
    const [partnerEmail, setPartnerEmail] = useState('')
    const [partnerPhone, setPartnerPhone] = useState('')
    const [validityDate, setValidityDate] = useState('')
    const [notes, setNotes] = useState('Thanh to├ín qua chuyß╗ân khoß║ún:\nC├┤ng ty TNHH V├╡ Trß╗ìng Ngh─⌐a\nTK: 007.100.238.2826\nNg├ón h├áng Ngoß║íi th╞░╞íng Viß╗çt Nam (Vietcombank) ΓÇö CN Hß╗ô Ch├¡ Minh\nMST: 0303506388')
    const [lines, setLines] = useState<Line[]>([
        { id: '1', description: 'Thiß║┐t kß║┐ kiß║┐n tr├║c s╞í bß╗Ö', qty: 1, unitPrice: 0 },
        { id: '2', description: 'Thiß║┐t kß║┐ kiß║┐n tr├║c kß╗╣ thuß║¡t thi c├┤ng', qty: 1, unitPrice: 0 },
    ])
    const [milestones, setMilestones] = useState<Milestone[]>([
        { id: '1', name: 'Tß║ím ß╗⌐ng 30%', percent: 30, dueDate: '' },
        { id: '2', name: 'Ho├án th├ánh thiß║┐t kß║┐ c╞í sß╗ƒ', percent: 25, dueDate: '' },
        { id: '3', name: 'Ho├án th├ánh thiß║┐t kß║┐ kß╗╣ thuß║¡t', percent: 25, dueDate: '' },
        { id: '4', name: 'Nghiß╗çm thu ho├án c├┤ng', percent: 20, dueDate: '' },
    ])
    const [saving, setSaving] = useState(false)
    const [error, setError] = useState('')

    const totalAmount = lines.reduce((s, l) => s + l.qty * l.unitPrice, 0)
    const totalPercent = milestones.reduce((s, m) => s + m.percent, 0)

    function addLine() {
        setLines(prev => [...prev, { id: Date.now().toString(), description: '', qty: 1, unitPrice: 0 }])
    }
    function removeLine(id: string) {
        setLines(prev => prev.filter(l => l.id !== id))
    }
    function updateLine(id: string, field: keyof Line, value: string | number) {
        setLines(prev => prev.map(l => l.id === id ? { ...l, [field]: value } : l))
    }

    async function handleSave(state: string) {
        if (!partnerName.trim()) { setError('Vui l├▓ng nhß║¡p t├¬n kh├ích h├áng'); return }
        if (totalAmount <= 0) { setError('Tß╗òng gi├í trß╗ï phß║úi lß╗¢n h╞ín 0'); return }

        setError('')
        setSaving(true)
        try {
            const result = await createOrder({
                partnerName: partnerName.trim(),
                partnerEmail: partnerEmail || null,
                partnerPhone: partnerPhone || null,
                totalAmount,
                notes: notes || null,
            })
            if (!result.success) { setError(result.error); setSaving(false); return }

            // Add milestones
            for (let i = 0; i < milestones.length; i++) {
                const ms = milestones[i]
                if (ms.name.trim()) {
                    const msResult = await addMilestone({
                        orderId: result.data.id as string,
                        name: ms.name,
                        percent: ms.percent,
                        amount: Math.round(totalAmount * ms.percent / 100),
                        dueDate: ms.dueDate || null,
                        sequence: i + 1,
                        state: 'PENDING',
                    })
                    if (!msResult.success) { setError(msResult.error); setSaving(false); return }
                }
            }

            router.push('/sale')
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        } catch (err: any) {
            setError(err.message || 'Lß╗ùi khi l╞░u')
        } finally {
            setSaving(false)
        }
    }

    return (
        <>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16, fontSize: 13, color: '#8FA3BF' }}>
                <Link href="/sale" style={{ color: '#8FA3BF', textDecoration: 'none' }}>B├ío gi├í & H─É</Link>
                <span>ΓÇ║</span>
                <span style={{ color: '#0F1C2E', fontWeight: 600 }}>Tß║ío b├ío gi├í mß╗¢i</span>
            </div>

            <div className="page-header" style={{ marginBottom: 20 }}>
                <h1 className="page-title">Tß║ío B├ío gi├í mß╗¢i</h1>
                <div className="page-actions">
                    <Link href="/sale" className="btn btn-ghost btn-sm">Huß╗╖</Link>
                    <button className="btn btn-outline btn-sm" disabled={saving} onClick={() => handleSave('DRAFT')}>
                        {saving ? '...' : 'L╞░u nh├íp'}
                    </button>
                    <button className="btn btn-primary" disabled={saving} onClick={() => handleSave('SENT')}>
                        {saving ? 'ΓÅ│ ─Éang l╞░u...' : '≡ƒôñ Gß╗¡i cho kh├ích h├áng'}
                    </button>
                </div>
            </div>

            {error && (
                <div style={{ background: '#FEF2F2', border: '1px solid #FECACA', color: '#DC2626', padding: '10px 16px', borderRadius: 8, marginBottom: 16, fontSize: 13 }}>
                    {error}
                </div>
            )}

            <div className="grid-2" style={{ alignItems: 'flex-start', gap: 20 }}>
                {/* Left: form */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                    {/* Customer info */}
                    <div className="card" style={{ padding: 20 }}>
                        <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 16 }}>Th├┤ng tin kh├ích h├áng</div>
                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                            <div className="form-group" style={{ gridColumn: '1 / -1' }}>
                                <label className="form-label">T├¬n kh├ích h├áng *</label>
                                <input className="form-input" placeholder="├öng/B├á Nguyß╗àn V─ân A hoß║╖c T├¬n c├┤ng ty" value={partnerName} onChange={e => setPartnerName(e.target.value)} />
                            </div>
                            <div className="form-group">
                                <label className="form-label">Email</label>
                                <input className="form-input" type="email" placeholder="email@example.com" value={partnerEmail} onChange={e => setPartnerEmail(e.target.value)} />
                            </div>
                            <div className="form-group">
                                <label className="form-label">─Éiß╗çn thoß║íi</label>
                                <input className="form-input" placeholder="09xx xxx xxx" value={partnerPhone} onChange={e => setPartnerPhone(e.target.value)} />
                            </div>
                            <div className="form-group">
                                <label className="form-label">Hiß╗çu lß╗▒c ─æß║┐n</label>
                                <input className="form-input" type="date" value={validityDate} onChange={e => setValidityDate(e.target.value)} />
                            </div>
                        </div>
                    </div>

                    {/* Line items */}
                    <div className="card" style={{ padding: 20 }}>
                        <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 16 }}>Dß╗ïch vß╗Ñ / Hß║íng mß╗Ñc</div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                            {/* Header */}
                            <div style={{ display: 'grid', gridTemplateColumns: '1fr 80px 130px 130px 36px', gap: 8, fontSize: 11, fontWeight: 700, color: '#8FA3BF', textTransform: 'uppercase', letterSpacing: '0.05em', padding: '0 4px' }}>
                                <span>M├┤ tß║ú dß╗ïch vß╗Ñ</span>
                                <span style={{ textAlign: 'center' }}>SL</span>
                                <span style={{ textAlign: 'right' }}>─É╞ín gi├í</span>
                                <span style={{ textAlign: 'right' }}>Th├ánh tiß╗ün</span>
                                <span />
                            </div>

                            {lines.map(line => (
                                <div key={line.id} style={{ display: 'grid', gridTemplateColumns: '1fr 80px 130px 130px 36px', gap: 8 }}>
                                    <input className="form-input" value={line.description} placeholder="M├┤ tß║ú dß╗ïch vß╗Ñ..." onChange={e => updateLine(line.id, 'description', e.target.value)} />
                                    <input className="form-input" type="number" min="1" value={line.qty} style={{ textAlign: 'center' }} onChange={e => updateLine(line.id, 'qty', parseFloat(e.target.value) || 1)} />
                                    <input className="form-input" type="number" min="0" value={line.unitPrice || ''} placeholder="0" style={{ textAlign: 'right' }} onChange={e => updateLine(line.id, 'unitPrice', parseFloat(e.target.value) || 0)} />
                                    <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end', fontWeight: 700, fontSize: 13, color: '#1F3A5F', padding: '0 4px' }}>
                                        {formatCurrency(line.qty * line.unitPrice)}
                                    </div>
                                    <button onClick={() => removeLine(line.id)} style={{ border: 'none', background: 'transparent', cursor: 'pointer', color: '#8FA3BF', padding: 4 }}>Γ£ò</button>
                                </div>
                            ))}

                            <button onClick={addLine} className="btn btn-ghost btn-sm" style={{ width: 'fit-content', marginTop: 4, border: '1.5px dashed #CBD5E1', borderRadius: 6 }}>
                                + Th├¬m d├▓ng
                            </button>

                            {/* Total */}
                            <div style={{ display: 'flex', justifyContent: 'flex-end', padding: '12px 4px 0', borderTop: '2px solid #F0F2F5', marginTop: 8 }}>
                                <div style={{ textAlign: 'right' }}>
                                    <div style={{ fontSize: 12, color: '#8FA3BF', marginBottom: 4 }}>Tß╗òng gi├í trß╗ï hß╗úp ─æß╗ông</div>
                                    <div style={{ fontSize: 24, fontWeight: 800, color: '#1F3A5F' }}>{formatCurrency(totalAmount)}</div>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Notes */}
                    <div className="card" style={{ padding: 20 }}>
                        <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 12 }}>Ghi ch├║ / ─Éiß╗üu khoß║ún</div>
                        <textarea className="form-textarea" rows={3} placeholder="─Éiß╗üu khoß║ún thanh to├ín, ghi ch├║ ─æß║╖c biß╗çt..." value={notes} onChange={e => setNotes(e.target.value)} />
                    </div>
                </div>

                {/* Right: milestones */}
                <div className="card" style={{ padding: 20 }}>
                    <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>Lß╗ïch thanh to├ín Milestones</div>
                    <div style={{ fontSize: 12, color: '#8FA3BF', marginBottom: 16 }}>
                        Tß╗òng: {totalPercent}% {totalPercent !== 100 && <span style={{ color: '#EF4444' }}>(cß║ºn = 100%)</span>}
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                        {milestones.map((ms, i) => (
                            <div key={ms.id} style={{ border: '1.5px solid #E2E8F0', borderRadius: 10, padding: '14px 16px' }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 }}>
                                    <div style={{ width: 22, height: 22, borderRadius: '50%', background: '#EFF3FA', color: '#1F3A5F', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 800, fontSize: 12, flexShrink: 0 }}>
                                        {i + 1}
                                    </div>
                                    <input className="form-input" value={ms.name} onChange={e => setMilestones(prev => prev.map(m => m.id === ms.id ? { ...m, name: e.target.value } : m))} />
                                </div>
                                <div style={{ display: 'grid', gridTemplateColumns: '80px 1fr 1fr', gap: 8 }}>
                                    <div className="form-group">
                                        <label className="form-label">%</label>
                                        <input className="form-input" type="number" value={ms.percent} onChange={e => setMilestones(prev => prev.map(m => m.id === ms.id ? { ...m, percent: parseFloat(e.target.value) || 0 } : m))} />
                                    </div>
                                    <div className="form-group">
                                        <label className="form-label">Sß╗æ tiß╗ün</label>
                                        <div style={{ padding: '9px 12px', background: '#F8F9FB', borderRadius: 4, fontSize: 13, fontWeight: 700, color: '#1F3A5F', border: '1.5px solid #E2E8F0' }}>
                                            {formatCurrency(totalAmount * ms.percent / 100)}
                                        </div>
                                    </div>
                                    <div className="form-group">
                                        <label className="form-label">─Éß║┐n hß║ín</label>
                                        <input className="form-input" type="date" value={ms.dueDate} onChange={e => setMilestones(prev => prev.map(m => m.id === ms.id ? { ...m, dueDate: e.target.value } : m))} />
                                    </div>
                                </div>
                            </div>
                        ))}
                        <button onClick={() => setMilestones(prev => [...prev, { id: Date.now().toString(), name: `Milestone ${prev.length + 1}`, percent: 0, dueDate: '' }])}
                            className="btn btn-ghost btn-sm" style={{ border: '1.5px dashed #CBD5E1', borderRadius: 6 }}>
                            + Th├¬m milestone
                        </button>
                    </div>
                </div>
            </div>
        </>
    )
}

import Link from 'next/link'
import { formatCurrency, formatDate } from '@/lib/utils'
import { getQuotations, getContracts } from '@/lib/actions/sale'
import SalePageTabs from '@/components/SalePageTabs'

export const dynamic = 'force-dynamic'

export default async function SalePage() {
    const [quotations, contracts] = await Promise.all([getQuotations(), getContracts()])

    return <SalePageTabs quotations={quotations} contracts={contracts} />
}

'use client'

import { useState, useMemo } from 'react'
import { saveWeekTimesheets } from '@/lib/actions/timesheets'
import { useToast, ToastContainer } from '@/components/Toast'

interface TimesheetEntry {
    id: string
    projectId: string
    projectName: string
    date: string
    hours: number
    description: string | null
}

interface Project {
    id: string
    name: string
    code: string | null
}

interface Props {
    weekDates: string[]
    monday: string
    timesheets: TimesheetEntry[]
    projects: Project[]
    employeeId?: string
}

const dayLabels = ['Thß╗⌐ 2', 'Thß╗⌐ 3', 'Thß╗⌐ 4', 'Thß╗⌐ 5', 'Thß╗⌐ 6', 'Thß╗⌐ 7']
const projectColors = ['#1F3A5F', '#C9A84C', '#22C55E', '#3B82F6', '#8B5CF6', '#EC4899', '#F59E0B', '#14B8A6']

export default function TimesheetGrid({ weekDates, monday, timesheets, projects, employeeId }: Props) {
    const { toasts, addToast } = useToast()
    const [saving, setSaving] = useState(false)

    const initialEntries = useMemo(() => {
        const map: Record<string, Record<string, number>> = {}
        const projectIds = new Set(timesheets.map(t => t.projectId))
        projects.forEach(p => projectIds.add(p.id))

        projectIds.forEach(pid => {
            map[pid] = {}
            weekDates.forEach((date, i) => {
                const entry = timesheets.find(t => t.projectId === pid && t.date === date)
                map[pid][String(i)] = entry?.hours ?? 0
            })
        })
        return map
    }, [timesheets, projects, weekDates])

    const [entries, setEntries] = useState(initialEntries)

    const visibleProjects = projects.filter(p => {
        const projEntries = entries[p.id]
        if (!projEntries) return false
        return Object.values(projEntries).some(h => h > 0) || true
    }).slice(0, 10)

    const totalHours = Object.values(entries).reduce((total, proj) =>
        total + Object.values(proj).reduce((s, h) => s + h, 0), 0)

    const dailyTotals = dayLabels.map((_, di) =>
        Object.values(entries).reduce((s, proj) => s + (proj[String(di)] || 0), 0)
    )

    const dateLabels = weekDates.map(d => {
        const date = new Date(d)
        return `${String(date.getDate()).padStart(2, '0')}/${String(date.getMonth() + 1).padStart(2, '0')}`
    })

    async function handleSave() {
        if (!employeeId) { addToast('Kh├┤ng t├¼m thß║Ñy nh├ón vi├¬n', 'error'); return }
        setSaving(true)
        try {
            const allEntries: { projectId: string; date: string; hours: number }[] = []
            for (const [projectId, days] of Object.entries(entries)) {
                for (const [dayIdx, hours] of Object.entries(days)) {
                    allEntries.push({ projectId, date: weekDates[Number(dayIdx)], hours })
                }
            }
            await saveWeekTimesheets(employeeId, allEntries)
            addToast(`─É├ú l╞░u ${totalHours}h tuß║ºn n├áy`)
        } catch (err: unknown) { addToast(err instanceof Error ? err.message : 'Lß╗ùi', 'error') }
        finally { setSaving(false) }
    }

    return (
        <>
            <ToastContainer toasts={toasts} />

            <div className="page-header">
                <div className="page-header-left">
                    <h1 className="page-title">Timesheet</h1>
                    <p className="page-subtitle">
                        Tuß║ºn {dateLabels[0]} ΓÇô {dateLabels[5]} ΓÇö Tß╗òng: {totalHours}h / 48h
                    </p>
                </div>
                <div className="page-actions">
                    <button className="btn btn-primary btn-sm" onClick={handleSave} disabled={saving}>
                        {saving ? 'ΓÅ│ ─Éang l╞░u...' : '≡ƒÆ╛ L╞░u timesheet'}
                    </button>
                </div>
            </div>

            <div className="card" style={{ marginBottom: 20, padding: '16px 24px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
                    <span style={{ fontSize: 14, fontWeight: 600, color: '#4A5E78' }}>Tiß║┐n ─æß╗Ö tuß║ºn</span>
                    <span style={{ fontSize: 14, fontWeight: 700, color: totalHours >= 40 ? '#22C55E' : '#F59E0B' }}>
                        {totalHours}h / 48h ({Math.round(totalHours / 48 * 100)}%)
                    </span>
                </div>
                <div className="progress" style={{ height: 10 }}>
                    <div className="progress-bar" style={{ width: `${Math.min(100, totalHours / 48 * 100)}%` }} />
                </div>
            </div>

            <div className="card">
                <div style={{ overflowX: 'auto' }}>
                    <table className="data-table" style={{ minWidth: 700 }}>
                        <thead>
                            <tr>
                                <th style={{ width: 220 }}>Dß╗▒ ├ín</th>
                                {dayLabels.map((day, i) => (
                                    <th key={day} style={{ textAlign: 'center', width: 90 }}>
                                        <div style={{ fontWeight: 700 }}>{day}</div>
                                        <div style={{ fontWeight: 400, color: '#8FA3BF', fontSize: 11 }}>{dateLabels[i]}</div>
                                    </th>
                                ))}
                                <th style={{ textAlign: 'right' }}>Tß╗òng</th>
                            </tr>
                        </thead>
                        <tbody>
                            {visibleProjects.map((proj, idx) => {
                                const color = projectColors[idx % projectColors.length]
                                const projTotal = Object.values(entries[proj.id] || {}).reduce((s, h) => s + h, 0)
                                return (
                                    <tr key={proj.id}>
                                        <td>
                                            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                                <div style={{ width: 10, height: 10, borderRadius: 3, background: color, flexShrink: 0 }} />
                                                <span style={{ fontWeight: 600, fontSize: 13 }}>{proj.name}</span>
                                            </div>
                                        </td>
                                        {dayLabels.map((_, di) => {
                                            const val = entries[proj.id]?.[String(di)] || 0
                                            return (
                                                <td key={di} style={{ textAlign: 'center', padding: '8px' }}>
                                                    <input
                                                        type="number" min="0" max="12" step="0.5"
                                                        value={val || ''} placeholder="0"
                                                        onChange={e => {
                                                            const newVal = parseFloat(e.target.value) || 0
                                                            setEntries(prev => ({
                                                                ...prev,
                                                                [proj.id]: { ...prev[proj.id], [String(di)]: newVal }
                                                            }))
                                                        }}
                                                        style={{
                                                            width: 56, height: 36, textAlign: 'center',
                                                            border: `1.5px solid ${val > 0 ? color + '60' : '#E2E8F0'}`,
                                                            borderRadius: 6, fontSize: 13, fontWeight: val > 0 ? 700 : 400,
                                                            color: val > 0 ? color : '#8FA3BF',
                                                            background: val > 0 ? color + '08' : '#fff',
                                                            outline: 'none', transition: 'all 0.15s ease',
                                                        }}
                                                    />
                                                </td>
                                            )
                                        })}
                                        <td style={{ textAlign: 'right', fontWeight: 700, color: '#1F3A5F' }}>{projTotal}h</td>
                                    </tr>
                                )
                            })}
                            {visibleProjects.length === 0 && (
                                <tr><td colSpan={8} style={{ textAlign: 'center', color: '#8FA3BF', padding: 24 }}>Ch╞░a c├│ dß╗▒ ├ín n├áo</td></tr>
                            )}
                        </tbody>
                        <tfoot>
                            <tr style={{ background: '#F8F9FB' }}>
                                <td style={{ fontWeight: 700, fontSize: 13, color: '#4A5E78' }}>Tß╗òng ng├áy</td>
                                {dailyTotals.map((total, i) => (
                                    <td key={i} style={{ textAlign: 'center', fontWeight: 700, color: total >= 8 ? '#22C55E' : total > 0 ? '#F59E0B' : '#CBD5E1' }}>
                                        {total > 0 ? `${total}h` : 'ΓÇö'}
                                    </td>
                                ))}
                                <td style={{ textAlign: 'right', fontWeight: 800, color: '#1F3A5F', fontSize: 15 }}>{totalHours}h</td>
                            </tr>
                        </tfoot>
                    </table>
                </div>
            </div>
        </>
    )
}

'use client'

import { useState, useRef, useCallback } from 'react'
import { deleteAttachment } from '@/lib/actions/attachments'
import { useToast, ToastContainer } from '@/components/Toast'

const FILE_ICONS: Record<string, string> = {
    'application/pdf': '≡ƒôä',
    'application/msword': '≡ƒô¥',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document': '≡ƒô¥',
    'application/vnd.ms-excel': '≡ƒôè',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': '≡ƒôè',
    'image/png': '≡ƒû╝∩╕Å',
    'image/jpeg': '≡ƒû╝∩╕Å',
    'image/webp': '≡ƒû╝∩╕Å',
}

function formatSize(bytes: number) {
    if (bytes < 1024) return `${bytes} B`
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

function getPublicUrl(storagePath: string) {
    const base = process.env.NEXT_PUBLIC_SUPABASE_URL
    return `${base}/storage/v1/object/public/documents/${storagePath}`
}

function formatTime(dateStr: string) {
    const d = new Date(dateStr)
    return `${d.getDate().toString().padStart(2, '0')}/${(d.getMonth() + 1).toString().padStart(2, '0')}/${d.getFullYear()} ${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}`
}

type Props = {
    entityType: string
    entityId: string
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    initialFiles?: any[]
}

export default function AttachmentPanel({ entityType, entityId, initialFiles = [] }: Props) {
    const { toasts, addToast } = useToast()
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const [files, setFiles] = useState<any[]>(initialFiles)
    const [uploading, setUploading] = useState(false)
    const [dragOver, setDragOver] = useState(false)
    const [previewUrl, setPreviewUrl] = useState<string | null>(null)
    const [previewType, setPreviewType] = useState<string>('')
    const inputRef = useRef<HTMLInputElement>(null)

    const handleUpload = useCallback(async (fileList: FileList | null) => {
        if (!fileList || fileList.length === 0) return
        setUploading(true)

        for (const file of Array.from(fileList)) {
            if (file.size > 10 * 1024 * 1024) {
                addToast(`"${file.name}" qu├í lß╗¢n (tß╗æi ─æa 10MB)`, 'error')
                continue
            }

            const formData = new FormData()
            formData.append('file', file)
            formData.append('entityType', entityType)
            formData.append('entityId', entityId)

            try {
                const res = await fetch('/api/upload', { method: 'POST', body: formData })
                const data = await res.json()
                if (!res.ok) throw new Error(data.error || 'Upload failed')
                setFiles(prev => [data, ...prev])
                addToast(`─É├ú upload "${file.name}"`)
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            } catch (err: any) {
                addToast(err.message, 'error')
            }
        }
        setUploading(false)
        if (inputRef.current) inputRef.current.value = ''
    }, [entityType, entityId, addToast])

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    async function handleDelete(attachment: any) {
        if (!confirm(`X├│a file "${attachment.fileName}"?`)) return
        try {
            await deleteAttachment(attachment.id)
            setFiles(prev => prev.filter(f => f.id !== attachment.id))
            addToast('─É├ú x├│a file')
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        } catch (err: any) {
            addToast(err.message, 'error')
        }
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    function handlePreview(attachment: any) {
        const url = getPublicUrl(attachment.storagePath)
        setPreviewUrl(url)
        setPreviewType(attachment.fileType)
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    function handleDownload(attachment: any) {
        const url = getPublicUrl(attachment.storagePath)
        const a = document.createElement('a')
        a.href = url
        a.download = attachment.fileName
        a.target = '_blank'
        a.click()
    }

    return (
        <>
            <ToastContainer toasts={toasts} />

            {/* Preview Modal */}
            {previewUrl && (
                <div
                    style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.6)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}
                    onClick={() => setPreviewUrl(null)}
                >
                    <div style={{ background: '#fff', borderRadius: 16, width: '80vw', maxWidth: 900, height: '80vh', display: 'flex', flexDirection: 'column', overflow: 'hidden' }} onClick={e => e.stopPropagation()}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 20px', borderBottom: '1px solid #E2E8F0' }}>
                            <span style={{ fontWeight: 700, fontSize: 14 }}>Xem t├ái liß╗çu</span>
                            <button onClick={() => setPreviewUrl(null)} style={{ border: 'none', background: 'none', fontSize: 20, cursor: 'pointer', color: '#8FA3BF' }}>Γ£ò</button>
                        </div>
                        <div style={{ flex: 1, overflow: 'auto' }}>
                            {previewType.startsWith('image/') ? (
                                <img src={previewUrl} alt="Preview" style={{ maxWidth: '100%', display: 'block', margin: '0 auto' }} />
                            ) : previewType === 'application/pdf' ? (
                                <iframe src={previewUrl} style={{ width: '100%', height: '100%', border: 'none' }} />
                            ) : (
                                <div style={{ textAlign: 'center', padding: 60, color: '#8FA3BF' }}>
                                    <div style={{ fontSize: 48, marginBottom: 16 }}>≡ƒôÄ</div>
                                    <p>Kh├┤ng thß╗â xem tr╞░ß╗¢c loß║íi file n├áy</p>
                                    <a href={previewUrl} target="_blank" className="btn btn-primary btn-sm" style={{ marginTop: 12 }}>
                                        Tß║úi xuß╗æng
                                    </a>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}

            <div className="card" style={{ padding: 20 }}>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 16 }}>≡ƒôÄ T├ái liß╗çu ─æ├¡nh k├¿m</div>

                {/* Drop Zone */}
                <div
                    onDragOver={e => { e.preventDefault(); setDragOver(true) }}
                    onDragLeave={() => setDragOver(false)}
                    onDrop={e => { e.preventDefault(); setDragOver(false); handleUpload(e.dataTransfer.files) }}
                    onClick={() => inputRef.current?.click()}
                    style={{
                        border: `2px dashed ${dragOver ? '#3B82F6' : '#CBD5E1'}`,
                        borderRadius: 12,
                        padding: uploading ? '16px' : '24px',
                        textAlign: 'center',
                        cursor: 'pointer',
                        background: dragOver ? '#EFF6FF' : '#FAFBFC',
                        transition: 'all .2s ease',
                        marginBottom: files.length > 0 ? 16 : 0,
                    }}
                >
                    <input ref={inputRef} type="file" multiple hidden onChange={e => handleUpload(e.target.files)} accept=".pdf,.doc,.docx,.xls,.xlsx,.png,.jpg,.jpeg,.webp" />
                    {uploading ? (
                        <div style={{ color: '#3B82F6', fontWeight: 600, fontSize: 13 }}>ΓÅ│ ─Éang upload...</div>
                    ) : (
                        <>
                            <div style={{ fontSize: 28, marginBottom: 6 }}>≡ƒôñ</div>
                            <div style={{ fontSize: 13, color: '#4A5E78', fontWeight: 500 }}>K├⌐o thß║ú file hoß║╖c <span style={{ color: '#3B82F6', fontWeight: 700 }}>nhß║Ñn ─æß╗â chß╗ìn</span></div>
                            <div style={{ fontSize: 11, color: '#8FA3BF', marginTop: 4 }}>PDF, Word, Excel, ß║ónh ΓÇö Tß╗æi ─æa 10MB</div>
                        </>
                    )}
                </div>

                {/* File List */}
                {files.length > 0 && (
                    <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                        {files.map(f => (
                            <div key={f.id} style={{
                                display: 'flex', alignItems: 'center', gap: 12,
                                padding: '10px 14px', borderRadius: 10, background: '#F8F9FB',
                                border: '1px solid #E2E8F0',
                            }}>
                                <div style={{ fontSize: 24, flexShrink: 0 }}>{FILE_ICONS[f.fileType] || '≡ƒôÄ'}</div>
                                <div style={{ flex: 1, overflow: 'hidden' }}>
                                    <div style={{ fontSize: 13, fontWeight: 600, color: '#0F1C2E', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                        {f.fileName}
                                    </div>
                                    <div style={{ fontSize: 11, color: '#8FA3BF' }}>
                                        {formatSize(f.fileSize)} ΓÇó {formatTime(f.createdAt)}
                                    </div>
                                </div>
                                <div style={{ display: 'flex', gap: 4, flexShrink: 0 }}>
                                    {(f.fileType.startsWith('image/') || f.fileType === 'application/pdf') && (
                                        <button onClick={() => handlePreview(f)} className="btn btn-ghost btn-sm" style={{ padding: '4px 8px', fontSize: 12 }}>≡ƒæü∩╕Å</button>
                                    )}
                                    <button onClick={() => handleDownload(f)} className="btn btn-ghost btn-sm" style={{ padding: '4px 8px', fontSize: 12 }}>Γ¼ç∩╕Å</button>
                                    <button onClick={() => handleDelete(f)} className="btn btn-ghost btn-sm" style={{ padding: '4px 8px', fontSize: 12, color: '#EF4444' }}>≡ƒùæ∩╕Å</button>
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>
        </>
    )
}

'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { formatCurrency, formatDate } from '@/lib/utils'
import { updateProjectState, createPhase, updatePhase, deletePhase, createTask, updateTask, deleteTask } from '@/lib/actions/projects'
import { useToast, ToastContainer } from '@/components/Toast'

interface ProjectPhase { id: string; name: string; state: string; sequence: number; projectId: string }
interface ProjectTask { id: string; name: string; state: string; priority: string; phaseId: string | null; projectId: string }
interface ProjectTimesheet { hours: number | string }
interface ProjectInvoice { id: string; name: string; state: string; amountTotal: number | string; invoiceDate?: string }
interface ProjectData {
    id: string; name: string; code?: string | null; state: string; budget?: number | string | null
    partnerName?: string | null; manager?: { name: string | null } | null; managerId?: string | null
    phases?: ProjectPhase[]; tasks?: ProjectTask[]; timesheets?: ProjectTimesheet[]; invoices?: ProjectInvoice[]
    [key: string]: unknown
}

const stateColors: Record<string, string> = { DRAFT: 'muted', ACTIVE: 'success', PAUSED: 'warning', DONE: 'primary', CANCELLED: 'danger' }
const stateLabels: Record<string, string> = { DRAFT: 'Nh├íp', ACTIVE: '─Éang thß╗▒c hiß╗çn', PAUSED: 'Tß║ím dß╗½ng', DONE: 'Ho├án th├ánh', CANCELLED: '─É├ú huß╗╖' }
const stateFlow: Record<string, { next: string; label: string }[]> = {
    DRAFT: [{ next: 'ACTIVE', label: 'Γû╢∩╕Å Bß║»t ─æß║ºu' }],
    ACTIVE: [{ next: 'PAUSED', label: 'ΓÅ╕ Tß║ím dß╗½ng' }, { next: 'DONE', label: '≡ƒÅü Ho├án th├ánh' }],
    PAUSED: [{ next: 'ACTIVE', label: 'Γû╢∩╕Å Tiß║┐p tß╗Ñc' }],
    DONE: [], CANCELLED: [{ next: 'DRAFT', label: 'Γå⌐ Mß╗ƒ lß║íi' }],
}
const phaseLabels: Record<string, string> = { TODO: 'Chß╗¥', IN_PROGRESS: '─Éang l├ám', DONE: 'Xong' }
const taskLabels: Record<string, string> = { TODO: 'Chß╗¥', IN_PROGRESS: '─Éang l├ám', REVIEW: 'Review', DONE: 'Xong' }

export default function ProjectDetail({ project: initProject }: { project: ProjectData }) {
    const router = useRouter()
    const { toasts, addToast } = useToast()
    const [project, setProject] = useState(initProject)
    const [phases, setPhases] = useState(initProject.phases || [])
    const [tasks, setTasks] = useState(initProject.tasks || [])
    const [showAddPhase, setShowAddPhase] = useState(false)
    const [showAddTask, setShowAddTask] = useState<string | null>(null)
    const [saving, setSaving] = useState(false)

    const transitions = stateFlow[project.state] || []
    const totalHours = (project.timesheets || []).reduce((s: number, t: ProjectTimesheet) => s + Number(t.hours || 0), 0)

    async function handleState(nextState: string) {
        try {
            const updated = await updateProjectState(project.id, nextState)
            setProject((p: ProjectData) => ({ ...p, ...updated }))
            addToast(`─É├ú chuyß╗ân sang "${stateLabels[nextState]}"`)
        } catch (err: unknown) { addToast(err instanceof Error ? err.message : 'Lß╗ùi', 'error') }
    }

    async function handleAddPhase(fd: FormData) {
        const name = fd.get('name') as string
        if (!name) return
        try {
            const ph = await createPhase({ projectId: project.id, name, sequence: phases.length, state: 'TODO' })
            setPhases((prev: ProjectPhase[]) => [...prev, ph as unknown as ProjectPhase])
            setShowAddPhase(false)
            addToast(`─É├ú th├¬m phase "${name}"`)
        } catch (err: unknown) { addToast(err instanceof Error ? err.message : 'Lß╗ùi', 'error') }
    }

    async function handlePhaseState(phaseId: string, state: string) {
        try {
            const updated = await updatePhase(phaseId, { state })
            setPhases((prev: ProjectPhase[]) => prev.map(p => p.id === phaseId ? { ...p, ...updated } : p))
            addToast(`Phase ΓåÆ ${phaseLabels[state]}`)
        } catch (err: unknown) { addToast(err instanceof Error ? err.message : 'Lß╗ùi', 'error') }
    }

    async function handleDeletePhase(phaseId: string) {
        if (!confirm('X├│a phase v├á tß║Ñt cß║ú tasks trong ─æ├│?')) return
        try {
            await deletePhase(phaseId)
            setPhases((prev: ProjectPhase[]) => prev.filter(p => p.id !== phaseId))
            setTasks((prev: ProjectTask[]) => prev.filter(t => t.phaseId !== phaseId))
            addToast('─É├ú x├│a phase')
        } catch (err: unknown) { addToast(err instanceof Error ? err.message : 'Lß╗ùi', 'error') }
    }

    async function handleAddTask(fd: FormData) {
        const name = fd.get('name') as string
        const phaseId = fd.get('phaseId') as string
        if (!name) return
        try {
            const task = await createTask({ projectId: project.id, phaseId, name, state: 'TODO', priority: 'NORMAL' })
            setTasks((prev: ProjectTask[]) => [...prev, task as unknown as ProjectTask])
            setShowAddTask(null)
            addToast(`─É├ú th├¬m task "${name}"`)
        } catch (err: unknown) { addToast(err instanceof Error ? err.message : 'Lß╗ùi', 'error') }
    }

    async function handleTaskState(taskId: string, state: string) {
        try {
            const updated = await updateTask(taskId, { state })
            setTasks((prev: ProjectTask[]) => prev.map(t => t.id === taskId ? { ...t, ...updated } : t))
        } catch (err: unknown) { addToast(err instanceof Error ? err.message : 'Lß╗ùi', 'error') }
    }

    async function handleDeleteTask(taskId: string) {
        try {
            await deleteTask(taskId)
            setTasks((prev: ProjectTask[]) => prev.filter(t => t.id !== taskId))
            addToast('─É├ú x├│a task')
        } catch (err: unknown) { addToast(err instanceof Error ? err.message : 'Lß╗ùi', 'error') }
    }

    const doneCount = tasks.filter((t: ProjectTask) => t.state === 'DONE').length
    const progress = tasks.length > 0 ? Math.round(doneCount / tasks.length * 100) : 0

    return (
        <>
            <ToastContainer toasts={toasts} />

            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16, fontSize: 13, color: '#8FA3BF' }}>
                <Link href="/projects" style={{ color: '#8FA3BF', textDecoration: 'none' }}>Dß╗▒ ├ín</Link>
                <span>ΓÇ║</span>
                <span style={{ color: '#0F1C2E', fontWeight: 600 }}>{project.name}</span>
            </div>

            <div className="page-header" style={{ marginBottom: 20 }}>
                <div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6 }}>
                        <h1 className="page-title" style={{ marginBottom: 0 }}>{project.name}</h1>
                        <span className={`badge badge-${stateColors[project.state]}`}>{stateLabels[project.state]}</span>
                        {project.code && <span style={{ fontSize: 12, color: '#8FA3BF' }}>{project.code}</span>}
                    </div>
                    <p className="page-subtitle">{project.partnerName ?? project.manager?.name ?? 'ΓÇö'} ΓÇó Budget: {formatCurrency(Number(project.budget ?? 0))}</p>
                </div>
                <div className="page-actions">
                    {transitions.map(t => (
                        <button key={t.next} className="btn btn-primary btn-sm" onClick={() => handleState(t.next)}>{t.label}</button>
                    ))}
                </div>
            </div>

            {/* KPIs */}
            <div className="grid-4" style={{ marginBottom: 20 }}>
                {[
                    { label: 'Tiß║┐n ─æß╗Ö', value: `${progress}%`, icon: '≡ƒôè' },
                    { label: 'Tasks', value: `${doneCount}/${tasks.length}`, icon: 'Γ£à' },
                    { label: 'Giß╗¥ c├┤ng', value: `${totalHours}h`, icon: 'ΓÅ▒∩╕Å' },
                    { label: 'Ho├í ─æ╞ín', value: `${(project.invoices || []).length}`, icon: '≡ƒôä' },
                ].map(k => (
                    <div key={k.label} className="kpi-card" style={{ padding: 16 }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                            <div>
                                <div className="kpi-label">{k.label}</div>
                                <div className="kpi-value" style={{ fontSize: 22, marginTop: 4 }}>{k.value}</div>
                            </div>
                            <div style={{ fontSize: 24 }}>{k.icon}</div>
                        </div>
                    </div>
                ))}
            </div>

            {/* Phases + Tasks */}
            <div className="card" style={{ padding: 20, marginBottom: 20 }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                    <div style={{ fontWeight: 700, fontSize: 16 }}>Giai ─æoß║ín & C├┤ng viß╗çc</div>
                    <button className="btn btn-ghost btn-sm" onClick={() => setShowAddPhase(true)}>+ Phase</button>
                </div>

                {phases.length === 0 && !showAddPhase && (
                    <div style={{ textAlign: 'center', color: '#8FA3BF', padding: 32 }}>Ch╞░a c├│ phase. Nhß║Ñn "+ Phase" ─æß╗â th├¬m.</div>
                )}

                {phases.map((phase: ProjectPhase) => {
                    const phaseTasks = tasks.filter((t: ProjectTask) => t.phaseId === phase.id)
                    return (
                        <div key={phase.id} style={{ border: '1.5px solid #E2E8F0', borderRadius: 12, marginBottom: 12, overflow: 'hidden' }}>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '12px 16px', background: '#F8F9FB' }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                                    <span style={{ fontWeight: 700, fontSize: 14 }}>{phase.name}</span>
                                    <select value={phase.state} onChange={e => handlePhaseState(phase.id, e.target.value)}
                                        style={{ fontSize: 11, border: '1px solid #CBD5E1', borderRadius: 6, padding: '2px 6px', cursor: 'pointer' }}>
                                        <option value="TODO">Chß╗¥</option>
                                        <option value="IN_PROGRESS">─Éang l├ám</option>
                                        <option value="DONE">Xong</option>
                                    </select>
                                </div>
                                <div style={{ display: 'flex', gap: 6 }}>
                                    <button className="btn btn-ghost btn-sm" style={{ fontSize: 11 }} onClick={() => setShowAddTask(phase.id)}>+ Task</button>
                                    <button style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#EF4444', fontSize: 12 }}
                                        onClick={() => handleDeletePhase(phase.id)}>Γ£ò</button>
                                </div>
                            </div>

                            <div style={{ padding: phaseTasks.length > 0 || showAddTask === phase.id ? '8px 16px 12px' : 0 }}>
                                {phaseTasks.map((task: ProjectTask) => (
                                    <div key={task.id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '8px 0', borderBottom: '1px solid #F0F2F5' }}>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                            <input type="checkbox" checked={task.state === 'DONE'}
                                                onChange={() => handleTaskState(task.id, task.state === 'DONE' ? 'TODO' : 'DONE')}
                                                style={{ cursor: 'pointer' }} />
                                            <span style={{ fontSize: 13, textDecoration: task.state === 'DONE' ? 'line-through' : 'none', color: task.state === 'DONE' ? '#8FA3BF' : '#0F1C2E' }}>
                                                {task.name}
                                            </span>
                                        </div>
                                        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
                                            <select value={task.state} onChange={e => handleTaskState(task.id, e.target.value)}
                                                style={{ fontSize: 11, border: '1px solid #E2E8F0', borderRadius: 4, padding: '1px 4px' }}>
                                                <option value="TODO">Chß╗¥</option>
                                                <option value="IN_PROGRESS">─Éang l├ám</option>
                                                <option value="REVIEW">Review</option>
                                                <option value="DONE">Xong</option>
                                            </select>
                                            <button style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#CBD5E1', fontSize: 12 }}
                                                onClick={() => handleDeleteTask(task.id)}>Γ£ò</button>
                                        </div>
                                    </div>
                                ))}

                                {showAddTask === phase.id && (
                                    <form action={handleAddTask} style={{ display: 'flex', gap: 8, marginTop: 8 }}>
                                        <input type="hidden" name="phaseId" value={phase.id} />
                                        <input className="form-input" name="name" placeholder="T├¬n task..." autoFocus style={{ flex: 1, fontSize: 13 }} />
                                        <button className="btn btn-primary btn-sm" type="submit">Th├¬m</button>
                                        <button className="btn btn-ghost btn-sm" type="button" onClick={() => setShowAddTask(null)}>Huß╗╖</button>
                                    </form>
                                )}
                            </div>
                        </div>
                    )
                })}

                {showAddPhase && (
                    <form action={handleAddPhase} style={{ display: 'flex', gap: 8, marginTop: 8 }}>
                        <input className="form-input" name="name" placeholder="T├¬n phase..." autoFocus style={{ flex: 1 }} />
                        <button className="btn btn-primary btn-sm" type="submit">Th├¬m</button>
                        <button className="btn btn-ghost btn-sm" type="button" onClick={() => setShowAddPhase(false)}>Huß╗╖</button>
                    </form>
                )}
            </div>

            {/* Invoices */}
            <div className="card" style={{ padding: 20 }}>
                <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>Ho├í ─æ╞ín li├¬n quan</div>
                {(project.invoices || []).length === 0 ? (
                    <div style={{ textAlign: 'center', color: '#8FA3BF', padding: 24 }}>Ch╞░a c├│ ho├í ─æ╞ín</div>
                ) : (
                    <table className="data-table" style={{ fontSize: 13 }}>
                        <thead><tr><th>M├ú</th><th>Trß║íng th├íi</th><th style={{ textAlign: 'right' }}>Sß╗æ tiß╗ün</th><th>Ng├áy</th></tr></thead>
                        <tbody>
                            {(project.invoices || []).map((inv: ProjectInvoice) => (
                                <tr key={inv.id}>
                                    <td><Link href={`/finance/invoices/${inv.id}`} style={{ color: '#3B82F6', fontWeight: 600, textDecoration: 'none' }}>{inv.name}</Link></td>
                                    <td><span className={`badge badge-${inv.state === 'PAID' ? 'success' : 'muted'}`}>{inv.state}</span></td>
                                    <td style={{ textAlign: 'right', fontWeight: 700 }}>{formatCurrency(Number(inv.amountTotal))}</td>
                                    <td style={{ color: '#8FA3BF' }}>{inv.invoiceDate ? formatDate(String(inv.invoiceDate).split('T')[0]) : 'ΓÇö'}</td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                )}
            </div>
        </>
    )
}

