    convertOrderToProject, sendQuotation, approveQuotation, rejectQuotation,
    convertToContract, signContract,
} from '@/lib/actions/sale'
import { useToast, ToastContainer } from '@/components/Toast'
import AttachmentPanel from '@/components/AttachmentPanel'

const allStateColors: Record<string, string> = {
    DRAFT: 'muted', SENT: 'info', APPROVED: 'success', REJECTED: 'danger', EXPIRED: 'warning',
    NEGOTIATING: 'info', SIGNED: 'success', DONE: 'primary', CANCEL: 'danger',
}
const allStateLabels: Record<string, string> = {
    DRAFT: 'Nh├íp', SENT: '─É├ú gß╗¡i C─ÉT', APPROVED: 'C─ÉT duyß╗çt', REJECTED: 'Tß╗½ chß╗æi', EXPIRED: 'Hß║┐t hß║ín',
    NEGOTIATING: '─Éang ─æ├ám ph├ín', SIGNED: '─É├ú k├╜ H─É', DONE: 'Ho├án th├ánh', CANCEL: 'Huß╗╖', SALE: '─É├ú k├╜',
}
const msStateLabels: Record<string, string> = { PAID: '─É├ú thanh to├ín', INVOICED: '─É├ú xuß║Ñt H─É', PENDING: 'Ch╞░a ─æß║┐n hß║ín' }

type Line = { id?: string; description: string; qty: number; unitPrice: number }
type Milestone = { id?: string; name: string; percent: number; dueDate: string; state: string; amount?: number }

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default function SaleDetail({ order: initOrder, initialAttachments = [] }: { order: any; initialAttachments?: any[] }) {
    const router = useRouter()
    const { toasts, addToast } = useToast()
    const [order, setOrder] = useState(initOrder)
    const [editingLines, setEditingLines] = useState(false)
    const [editingMS, setEditingMS] = useState(false)
    const [lines, setLines] = useState<Line[]>(initOrder.lines || [])
    const [milestones, setMilestones] = useState<Milestone[]>(initOrder.milestones || [])
    const [saving, setSaving] = useState(false)
    const [rejectReason, setRejectReason] = useState('')
    const [showRejectDialog, setShowRejectDialog] = useState(false)

    const isQuotation = order.docType === 'QUOTATION'
    const isContract = order.docType === 'CONTRACT'
    const totalAmount = lines.reduce((s, l) => s + l.qty * l.unitPrice, 0)

    // ΓöÇΓöÇ Quotation actions ΓöÇΓöÇ
    async function handleSend() {
        if (!confirm(`Gß╗¡i b├ío gi├í "${order.name}" cho C─ÉT?`)) return
        const result = await sendQuotation(order.id)
        if (!result.success) { addToast(result.error, 'error'); return }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        setOrder((prev: any) => ({ ...prev, ...result.data }))
        addToast(`─É├ú gß╗¡i b├ío gi├í ${order.name} cho C─ÉT`)
    }

    async function handleApprove() {
        if (!confirm(`C─ÉT ─æ├ú duyß╗çt b├ío gi├í "${order.name}"?`)) return
        const result = await approveQuotation(order.id)
        if (!result.success) { addToast(result.error, 'error'); return }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        setOrder((prev: any) => ({ ...prev, ...result.data }))
        addToast(`C─ÉT ─æ├ú duyß╗çt b├ío gi├í ${order.name}`)
    }

    async function handleReject() {
        const result = await rejectQuotation(order.id, rejectReason)
        if (!result.success) { addToast(result.error, 'error'); return }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        setOrder((prev: any) => ({ ...prev, ...result.data }))
        setShowRejectDialog(false)
        addToast(`B├ío gi├í ${order.name} ─æ├ú bß╗ï tß╗½ chß╗æi`)
    }

    async function handleConvertToContract() {
        if (!confirm(`Chuyß╗ân b├ío gi├í "${order.name}" th├ánh Hß╗úp ─æß╗ông ─æ├ám ph├ín?`)) return
        const result = await convertToContract(order.id)
        if (!result.success) { addToast(result.error, 'error'); return }
        addToast(`─É├ú tß║ío hß╗úp ─æß╗ông ${result.data.name}`)
        router.push(`/sale/${result.data.id}`)
    }

    // ΓöÇΓöÇ Contract actions ΓöÇΓöÇ
    async function handleSign() {
        if (!confirm(`K├╜ hß╗úp ─æß╗ông "${order.name}"?`)) return
        const result = await signContract(order.id)
        if (!result.success) { addToast(result.error, 'error'); return }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        setOrder((prev: any) => ({ ...prev, ...result.data }))
        addToast(`─É├ú k├╜ hß╗úp ─æß╗ông ${order.name}`)
    }

    async function handleDone() {
        const result = await updateOrderState(order.id, 'DONE')
        if (!result.success) { addToast(result.error, 'error'); return }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        setOrder((prev: any) => ({ ...prev, ...result.data }))
        addToast(`─É├ú ho├án th├ánh ${order.name}`)
    }

    // ΓöÇΓöÇ Generic actions ΓöÇΓöÇ
    async function handleStateChange(nextState: string) {
        const result = await updateOrderState(order.id, nextState)
        if (!result.success) { addToast(result.error, 'error'); return }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        setOrder((prev: any) => ({ ...prev, ...result.data }))
        addToast(`─É├ú cß║¡p nhß║¡t trß║íng th├íi`)
    }

    async function handleSaveLines() {
        setSaving(true)
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const result = await saveOrderLines(order.id, lines as any)
        setSaving(false)
        if (!result.success) { addToast(result.error, 'error'); return }
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        setOrder((prev: any) => ({ ...prev, totalAmount }))
        setEditingLines(false)
        addToast('─É├ú cß║¡p nhß║¡t dß╗ïch vß╗Ñ')
    }

    async function handleSaveMS() {
        setSaving(true)
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const result = await saveMilestones(order.id, milestones as any)
        setSaving(false)
        if (!result.success) { addToast(result.error, 'error'); return }
        setEditingMS(false)
        addToast('─É├ú cß║¡p nhß║¡t milestones')
    }

    async function handleDelete() {
        if (!confirm(`X├│a "${order.name}"? Tß║Ñt cß║ú dß╗ïch vß╗Ñ v├á milestones sß║╜ bß╗ï x├│a.`)) return
        const result = await deleteOrder(order.id)
        if (!result.success) { addToast(result.error, 'error'); return }
        addToast('─É├ú x├│a'); router.push('/sale')
    }

    async function handleConvertToProject() {
        if (!confirm(`Tß║ío dß╗▒ ├ín tß╗½ "${order.name}"?`)) return
        const result = await convertOrderToProject(order.id)
        if (!result.success) { addToast(result.error, 'error'); return }
        addToast(`─É├ú tß║ío dß╗▒ ├ín ${result.data.code}`)
        router.push(`/projects/${result.data.id}`)
    }

    const totalPaid = milestones.filter(m => m.state === 'PAID').reduce((s, m) => s + Number(m.amount || 0), 0)
    const paidPercent = Number(order.totalAmount) > 0 ? Math.round(totalPaid / Number(order.totalAmount) * 100) : 0

    // ΓöÇΓöÇ Flow buttons based on docType + state ΓöÇΓöÇ
    function renderFlowButtons() {
        if (isQuotation) {
            switch (order.state) {
                case 'DRAFT':
                    return (
                        <>
                            <button className="btn btn-sm" style={{ background: '#3B82F6', color: '#fff', border: 'none' }} onClick={handleSend}>≡ƒôñ Gß╗¡i C─ÉT</button>
                            <button className="btn btn-ghost btn-sm" style={{ color: '#EF4444' }} onClick={() => handleStateChange('CANCEL')}>Huß╗╖</button>
                        </>
                    )
                case 'SENT':
                    return (
                        <>
                            <button className="btn btn-sm" style={{ background: '#22C55E', color: '#fff', border: 'none' }} onClick={handleApprove}>Γ£à C─ÉT duyß╗çt</button>
                            <button className="btn btn-sm" style={{ background: '#EF4444', color: '#fff', border: 'none' }} onClick={() => setShowRejectDialog(true)}>Γ¥î Tß╗½ chß╗æi</button>
                            <button className="btn btn-ghost btn-sm" onClick={() => handleStateChange('DRAFT')}>Γå⌐ Vß╗ü nh├íp</button>
                        </>
                    )
                case 'APPROVED':
                    return (
                        <button className="btn btn-sm" style={{ background: '#6366F1', color: '#fff', border: 'none' }} onClick={handleConvertToContract}>≡ƒô¥ Chuyß╗ân sang Hß╗úp ─æß╗ông</button>
                    )
                case 'REJECTED': case 'EXPIRED': case 'CANCEL':
                    return (
                        <button className="btn btn-ghost btn-sm" onClick={() => handleStateChange('DRAFT')}>Γå⌐ Mß╗ƒ lß║íi</button>
                    )
                default: return null
            }
        }

        if (isContract) {
            switch (order.state) {
                case 'NEGOTIATING':
                    return (
                        <>
                            <button className="btn btn-sm" style={{ background: '#22C55E', color: '#fff', border: 'none' }} onClick={handleSign}>Γ£à K├╜ hß╗úp ─æß╗ông</button>
                            <button className="btn btn-ghost btn-sm" style={{ color: '#EF4444' }} onClick={() => handleStateChange('CANCEL')}>Huß╗╖</button>
                        </>
                    )
                case 'SIGNED':
                    return (
                        <>
                            <button className="btn btn-sm" style={{ background: '#6366F1', color: '#fff', border: 'none' }} onClick={handleDone}>≡ƒÅü Ho├án th├ánh</button>
                            <button className="btn btn-accent btn-sm" onClick={handleConvertToProject}>≡ƒÅù∩╕Å Tß║ío dß╗▒ ├ín</button>
                        </>
                    )
                case 'CANCEL':
                    return <button className="btn btn-ghost btn-sm" onClick={() => handleStateChange('NEGOTIATING')}>Γå⌐ Mß╗ƒ lß║íi</button>
                default: return null
            }
        }

        return null
    }

    return (
        <>
            <ToastContainer toasts={toasts} />

            {/* Reject Dialog */}
            {showRejectDialog && (
                <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
                    <div style={{ background: '#fff', borderRadius: 16, padding: 28, width: 420, maxWidth: '90vw' }}>
                        <h3 style={{ margin: '0 0 16px', fontSize: 16 }}>L├╜ do tß╗½ chß╗æi</h3>
                        <textarea className="form-input" value={rejectReason} onChange={e => setRejectReason(e.target.value)}
                            rows={3} placeholder="Nhß║¡p l├╜ do C─ÉT tß╗½ chß╗æi..." style={{ width: '100%', resize: 'vertical' }} />
                        <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 16 }}>
                            <button className="btn btn-ghost btn-sm" onClick={() => setShowRejectDialog(false)}>Huß╗╖</button>
                            <button className="btn btn-sm" style={{ background: '#EF4444', color: '#fff', border: 'none' }} onClick={handleReject}>Tß╗½ chß╗æi</button>
                        </div>
                    </div>
                </div>
            )}

            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 16, fontSize: 13, color: '#8FA3BF' }}>
                <Link href="/sale" style={{ color: '#8FA3BF', textDecoration: 'none' }}>B├ío gi├í & H─É</Link>
                <span>ΓÇ║</span>
                <span style={{ color: '#0F1C2E', fontWeight: 600 }}>{order.name}</span>
            </div>

            {/* Header */}
            <div className="page-header" style={{ marginBottom: 20 }}>
                <div>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6 }}>
                        <h1 className="page-title" style={{ marginBottom: 0 }}>{order.name}</h1>
                        <span className={`badge badge-${allStateColors[order.state] || 'muted'}`}>{allStateLabels[order.state] || order.state}</span>
                        <span style={{ fontSize: 11, background: isQuotation ? '#EFF6FF' : '#F5F3FF', color: isQuotation ? '#3B82F6' : '#6366F1', padding: '2px 8px', borderRadius: 4, fontWeight: 700 }}>
                            {isQuotation ? '≡ƒôï B├ío gi├í' : '≡ƒô¥ Hß╗úp ─æß╗ông'}
                        </span>
                    </div>
                    <p className="page-subtitle">{order.partnerName} ΓÇó Tß╗òng: {formatCurrency(Number(order.totalAmount))}</p>
                </div>
                <div className="page-actions" style={{ flexWrap: 'wrap' }}>
                    {renderFlowButtons()}
                    <a href={`/api/pdf/${initOrder.id}`} target="_blank" className="btn btn-outline btn-sm" style={{ textDecoration: 'none' }}>≡ƒôä Xuß║Ñt PDF</a>
                    <button className="btn btn-ghost btn-sm" style={{ color: '#EF4444' }} onClick={handleDelete}>X├│a</button>
                </div>
            </div>

            {/* Linked quotation info */}
            {isContract && order.quotation && (
                <div className="card" style={{ padding: 16, marginBottom: 20, background: '#FAFBFC', border: '1.5px dashed #CBD5E1' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 12, fontSize: 13 }}>
                        <span style={{ color: '#8FA3BF' }}>Tß╗½ b├ío gi├í:</span>
                        <Link href={`/sale/${order.quotation.id}`} style={{ fontWeight: 700, color: '#3B82F6' }}>{order.quotation.name}</Link>
                        <span style={{ color: '#8FA3BF' }}>ΓÇö {order.quotation.partnerName} ΓÇö {formatCurrency(Number(order.quotation.totalAmount))}</span>
                    </div>
                </div>
            )}

            {/* Payment Progress (only for contracts) */}
            {isContract && (
                <div className="card" style={{ padding: 20, marginBottom: 20 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
                        <div style={{ fontWeight: 700, fontSize: 14 }}>Tiß║┐n ─æß╗Ö thanh to├ín</div>
                        <div style={{ fontSize: 14, fontWeight: 700, color: '#22C55E' }}>{formatCurrency(totalPaid)} / {formatCurrency(Number(order.totalAmount))}</div>
                    </div>
                    <div className="progress" style={{ height: 12, marginBottom: 8 }}>
                        <div className="progress-bar" style={{ width: `${paidPercent}%`, background: '#22C55E' }} />
                    </div>
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: '#8FA3BF' }}>
                        <span>─É├ú thu: {paidPercent}%</span>
                        <span>C├▓n lß║íi: {formatCurrency(Number(order.totalAmount) - totalPaid)}</span>
                    </div>
                </div>
            )}

            <div className="grid-2" style={{ alignItems: 'flex-start', gap: 20 }}>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
                    {/* Info */}
                    <div className="card" style={{ padding: 20 }}>
                        <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 14 }}>{isQuotation ? 'Th├┤ng tin b├ío gi├í' : 'Th├┤ng tin hß╗úp ─æß╗ông'}</div>
                        {[
                            { label: 'Kh├ích h├áng', value: order.partnerName },
                            { label: 'Email', value: order.partnerEmail ?? 'ΓÇö' },
                            { label: 'S─ÉT', value: order.partnerPhone ?? 'ΓÇö' },
                            { label: 'Ng├áy tß║ío', value: order.createdAt ? formatDate(String(order.createdAt).split('T')[0]) : 'ΓÇö' },
                            ...(isQuotation ? [
                                { label: 'Hiß╗çu lß╗▒c', value: order.validityDate ? formatDate(String(order.validityDate).split('T')[0]) : 'ΓÇö' },
                                ...(order.sentAt ? [{ label: 'Ng├áy gß╗¡i', value: formatDate(String(order.sentAt).split('T')[0]) }] : []),
                                ...(order.approvedAt ? [{ label: 'Ng├áy duyß╗çt', value: formatDate(String(order.approvedAt).split('T')[0]) }] : []),
                            ] : [
                                ...(order.signedAt ? [{ label: 'Ng├áy k├╜', value: formatDate(String(order.signedAt).split('T')[0]) }] : []),
                            ]),
                        ].map(({ label, value }) => (
                            <div key={label} style={{ display: 'flex', gap: 12, fontSize: 13, marginBottom: 8 }}>
                                <span style={{ color: '#8FA3BF', width: 100, flexShrink: 0 }}>{label}</span>
                                <span style={{ color: '#0F1C2E' }}>{value}</span>
                            </div>
                        ))}
                        {order.rejectedReason && (
                            <div style={{ marginTop: 8, padding: '8px 12px', background: '#FEF2F2', borderRadius: 8, fontSize: 13, color: '#DC2626' }}>
                                <strong>L├╜ do tß╗½ chß╗æi:</strong> {order.rejectedReason}
                            </div>
                        )}
                    </div>

                    {/* Lines */}
                    <div className="card" style={{ padding: 20 }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 14 }}>
                            <div style={{ fontWeight: 700, fontSize: 14 }}>Chi tiß║┐t dß╗ïch vß╗Ñ</div>
                            <button className="btn btn-ghost btn-sm" onClick={() => { if (editingLines) handleSaveLines(); else setEditingLines(true) }}>
                                {saving ? 'ΓÅ│' : editingLines ? '≡ƒÆ╛ L╞░u' : 'Γ£Å∩╕Å Sß╗¡a'}
                            </button>
                        </div>

                        {editingLines ? (
                            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                                {lines.map((line, i) => (
                                    <div key={i} style={{ display: 'grid', gridTemplateColumns: '1fr 60px 100px 30px', gap: 6 }}>
                                        <input className="form-input" value={line.description} placeholder="M├┤ tß║ú..."
                                            onChange={e => setLines(prev => prev.map((l, j) => j === i ? { ...l, description: e.target.value } : l))} />
                                        <input className="form-input" type="number" value={line.qty} style={{ textAlign: 'center' }}
                                            onChange={e => setLines(prev => prev.map((l, j) => j === i ? { ...l, qty: +e.target.value || 1 } : l))} />
                                        <input className="form-input" type="number" value={line.unitPrice || ''} placeholder="0" style={{ textAlign: 'right' }}
                                            onChange={e => setLines(prev => prev.map((l, j) => j === i ? { ...l, unitPrice: +e.target.value || 0 } : l))} />
                                        <button onClick={() => setLines(prev => prev.filter((_, j) => j !== i))}
                                            style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#8FA3BF' }}>Γ£ò</button>
                                    </div>
                                ))}
                                <button onClick={() => setLines(prev => [...prev, { description: '', qty: 1, unitPrice: 0 }])}
                                    className="btn btn-ghost btn-sm" style={{ border: '1.5px dashed #CBD5E1', width: 'fit-content' }}>+ Th├¬m d├▓ng</button>
                                <div style={{ textAlign: 'right', fontWeight: 800, fontSize: 16, color: '#1F3A5F', marginTop: 8 }}>
                                    Tß╗òng: {formatCurrency(totalAmount)}
                                </div>
                            </div>
                        ) : (
                            <table className="data-table" style={{ fontSize: 13 }}>
                                <thead><tr><th>M├┤ tß║ú</th><th style={{ textAlign: 'center' }}>SL</th><th style={{ textAlign: 'right' }}>─É╞ín gi├í</th><th style={{ textAlign: 'right' }}>Th├ánh tiß╗ün</th></tr></thead>
                                <tbody>
                                    {(order.lines || []).length === 0 ? (
                                        <tr><td colSpan={4} style={{ textAlign: 'center', color: '#8FA3BF', padding: 24 }}>Ch╞░a c├│ dß╗ïch vß╗Ñ</td></tr>
                                    // eslint-disable-next-line @typescript-eslint/no-explicit-any
                                    ) : (order.lines || []).map((l: any) => (
                                        <tr key={l.id}>
                                            <td style={{ fontWeight: 500 }}>{l.description}</td>
                                            <td style={{ textAlign: 'center', color: '#8FA3BF' }}>{l.qty}</td>
                                            <td style={{ textAlign: 'right', color: '#4A5E78' }}>{formatCurrency(Number(l.unitPrice || 0))}</td>
                                            <td style={{ textAlign: 'right', fontWeight: 700, color: '#1F3A5F' }}>{formatCurrency(Number(l.subtotal || 0))}</td>
                                        </tr>
                                    ))}
                                </tbody>
                                <tfoot><tr style={{ background: '#F8F9FB' }}>
                                    <td colSpan={3} style={{ fontWeight: 700, textAlign: 'right' }}>Tß╗òng</td>
                                    <td style={{ fontWeight: 800, textAlign: 'right', color: '#1F3A5F' }}>{formatCurrency(Number(order.totalAmount))}</td>
                                </tr></tfoot>
                            </table>
                        )}
                    </div>
                </div>

                {/* Right: Milestones (only for contracts) */}
                <div className="card" style={{ padding: 20 }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 16 }}>
                        <div style={{ fontWeight: 700, fontSize: 14 }}>Milestones</div>
                        {isContract && (
                            <button className="btn btn-ghost btn-sm" onClick={() => { if (editingMS) handleSaveMS(); else setEditingMS(true) }}>
                                {saving ? 'ΓÅ│' : editingMS ? '≡ƒÆ╛ L╞░u' : 'Γ£Å∩╕Å Sß╗¡a'}
                            </button>
                        )}
                    </div>

                    {editingMS ? (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                            {milestones.map((ms, i) => (
                                <div key={i} style={{ border: '1.5px solid #E2E8F0', borderRadius: 10, padding: 14 }}>
                                    <div style={{ display: 'flex', gap: 8, marginBottom: 8 }}>
                                        <input className="form-input" value={ms.name} placeholder="T├¬n milestone"
                                            onChange={e => setMilestones(prev => prev.map((m, j) => j === i ? { ...m, name: e.target.value } : m))} style={{ flex: 1 }} />
                                        <button onClick={() => setMilestones(prev => prev.filter((_, j) => j !== i))}
                                            style={{ border: 'none', background: 'none', cursor: 'pointer', color: '#EF4444' }}>Γ£ò</button>
                                    </div>
                                    <div style={{ display: 'grid', gridTemplateColumns: '80px 1fr', gap: 8 }}>
                                        <input className="form-input" type="number" value={ms.percent} placeholder="%"
                                            onChange={e => setMilestones(prev => prev.map((m, j) => j === i ? { ...m, percent: +e.target.value || 0 } : m))} />
                                        <input className="form-input" type="date" value={ms.dueDate || ''}
                                            onChange={e => setMilestones(prev => prev.map((m, j) => j === i ? { ...m, dueDate: e.target.value } : m))} />
                                    </div>
                                </div>
                            ))}
                            <button onClick={() => setMilestones(prev => [...prev, { name: `Milestone ${prev.length + 1}`, percent: 0, dueDate: '', state: 'PENDING' }])}
                                className="btn btn-ghost btn-sm" style={{ border: '1.5px dashed #CBD5E1' }}>+ Th├¬m milestone</button>
                            <div style={{ fontSize: 12, color: milestones.reduce((s, m) => s + m.percent, 0) === 100 ? '#22C55E' : '#EF4444', fontWeight: 600 }}>
                                Tß╗òng: {milestones.reduce((s, m) => s + m.percent, 0)}% {milestones.reduce((s, m) => s + m.percent, 0) !== 100 && '(cß║ºn = 100%)'}
                            </div>
                        </div>
                    ) : (
                        <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                            {(order.milestones || []).length === 0 ? (
                                <div style={{ textAlign: 'center', color: '#8FA3BF', padding: 32 }}>
